import assert from 'node:assert/strict';
import { test } from 'node:test';
import { mergeConfig } from '../src/config.js';

function freeze(value) {
  if (value && typeof value === 'object') {
    for (const child of Object.values(value)) freeze(child);
    Object.freeze(value);
  }
  return value;
}

test('flat merging, empty inputs, and explicit undefined retain existing semantics', () => {
  assert.deepEqual(mergeConfig({ a: 1, b: 2 }, { b: 3, c: 4 }), { a: 1, b: 3, c: 4 });
  assert.deepEqual(mergeConfig({}, {}), {});
  assert.deepEqual(mergeConfig({ a: 1 }, {}), { a: 1 });
  assert.deepEqual(mergeConfig({}, { a: 1 }), { a: 1 });
  const result = mergeConfig({ a: 1 }, { a: undefined });
  assert.equal(Object.hasOwn(result, 'a'), true);
  assert.equal(result.a, undefined);
});

test('non-plain overrides replace a default object whole', () => {
  class Box { constructor() { this.value = 7; } }
  const values = [null, undefined, 'text', 0, false, ['c'], new Date(0), new Box()];
  for (const value of values) {
    const defaults = freeze({ item: { retained: 1 }, untouched: true });
    const overrides = freeze({ item: value });
    const result = mergeConfig(defaults, overrides);
    assert.strictEqual(result.item, value);
    assert.equal(result.untouched, true);
    assert.deepEqual(defaults, { item: { retained: 1 }, untouched: true });
    assert.strictEqual(overrides.item, value);
  }
  assert.deepEqual(mergeConfig({ tags: ['a', 'b'] }, { tags: ['c'] }), { tags: ['c'] });
});

test('a plain object replaces a non-plain default without importing its properties', () => {
  class Box { constructor() { this.old = 1; } }
  for (const value of [null, undefined, 'abc', 3, false, ['a', 'b'], new Box()]) {
    const defaults = freeze({ item: value });
    const overrides = freeze({ item: { fresh: 2 } });
    assert.deepEqual(mergeConfig(defaults, overrides), { item: { fresh: 2 } });
    assert.strictEqual(defaults.item, value);
    assert.deepEqual(overrides, { item: { fresh: 2 } });
  }
});

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { mergeConfig } from '../src/config.js';

function freeze(value) {
  if (value && typeof value === 'object') {
    for (const child of Object.values(value)) freeze(child);
    Object.freeze(value);
  }
  return value;
}

test('merge recursively across siblings without modifying either input', () => {
  const defaults = freeze({
    server: { host: 'localhost', port: 8080, tls: { enabled: false, cert: { path: 'old', mode: 420 } } },
    client: { retries: 3, headers: { accept: 'json', auth: 'old' } },
    level: 'info'
  });
  const overrides = freeze({
    server: { port: 9090, tls: { enabled: true, cert: { path: 'new' } } },
    client: { headers: { auth: 'new' } },
    extra: { enabled: true }
  });
  const beforeDefaults = JSON.stringify(defaults);
  const beforeOverrides = JSON.stringify(overrides);
  assert.deepEqual(mergeConfig(defaults, overrides), {
    server: { host: 'localhost', port: 9090, tls: { enabled: true, cert: { path: 'new', mode: 420 } } },
    client: { retries: 3, headers: { accept: 'json', auth: 'new' } },
    level: 'info', extra: { enabled: true }
  });
  assert.equal(JSON.stringify(defaults), beforeDefaults);
  assert.equal(JSON.stringify(overrides), beforeOverrides);
});

test('empty nested overrides retain defaults and mixed leaf types replace whole', () => {
  const defaults = freeze({ section: { keep: { x: 1 }, tags: ['a', 'b'], disabled: { x: 1 }, text: { x: 1 }, count: { x: 1 }, unset: { x: 1 } } });
  const overrides = freeze({ section: { keep: {}, tags: ['c'], disabled: null, text: 'new', count: 0, unset: undefined, added: { x: 2 } } });
  assert.deepEqual(mergeConfig(defaults, overrides), {
    section: { keep: { x: 1 }, tags: ['c'], disabled: null, text: 'new', count: 0, unset: undefined, added: { x: 2 } }
  });
});

test('merging is not limited to a fixed nesting depth', () => {
  let defaults = { retained: 1, changed: 2 };
  let overrides = { changed: 3, added: 4 };
  let expected = { retained: 1, changed: 3, added: 4 };
  for (let i = 0; i < 40; i++) {
    defaults = { branch: defaults, sibling: i };
    overrides = { branch: overrides };
    expected = { branch: expected, sibling: i };
  }
  freeze(defaults);
  freeze(overrides);
  assert.deepEqual(mergeConfig(defaults, overrides), expected);
});

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { mergeConfig } from '../src/config.js';

const dictionary = entries => Object.assign(Object.create(null), entries);

test('null-prototype plain objects merge with both ordinary and null-prototype objects', () => {
  for (const makeDefault of [entries => ({ ...entries }), dictionary]) {
    for (const makeOverride of [entries => ({ ...entries }), dictionary]) {
      const leafDefault = Object.freeze(makeDefault({ retained: 1, changed: 2 }));
      const leafOverride = Object.freeze(makeOverride({ changed: 3, added: 4 }));
      const sectionDefault = Object.freeze(makeDefault({ leaf: leafDefault, sibling: true }));
      const sectionOverride = Object.freeze(makeOverride({ leaf: leafOverride }));
      const defaults = Object.freeze({ section: sectionDefault });
      const overrides = Object.freeze({ section: sectionOverride });
      const result = mergeConfig(defaults, overrides);
      assert.equal(result.section.sibling, true);
      assert.deepEqual({ ...result.section.leaf }, { retained: 1, changed: 3, added: 4 });
      assert.deepEqual({ ...leafDefault }, { retained: 1, changed: 2 });
      assert.deepEqual({ ...leafOverride }, { changed: 3, added: 4 });
      assert.strictEqual(defaults.section, sectionDefault);
      assert.strictEqual(overrides.section, sectionOverride);
    }
  }
});
